        in.nextToken();
        int N = (int) in.nval;
        in.nextToken();
        int D = (int) in.nval;
        int[] res = findPrimes(N, D);
        if (res.length == 0) {
            System.out.println(-1);
            return;
        }
        StringBuilder sb = new StringBuilder();
